 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Each occupied input cell expands into the complement of the input's
    # occupied-cell mask, with the original cell's color.
    pattern = [[0 if grid[r][c] else 1 for c in range(w)] for r in range(h)]
    out = [[0 for _ in range(w * 3)] for _ in range(h * 3)]
    for r in range(h):
        for c in range(w):
            value = grid[r][c]
            if value:
                for pr in range(h):
                    for pc in range(w):
                        if pattern[pr][pc]:
                            out[r * h + pr][c * w + pc] = value
    return out
